(W/'output/FOUNDATION_REPORT.md').write_text(report)
(W/'output/NOVELTY_AND_RESEARCH_DECISION.md').write_text((W/'lanes/PRIOR_ART.md').read_text())
print('Integrated report words:',len(report.split()))
